"use strict";
/**
 * type3.js, the ANS-104 signature type 3 (EVM, secp256k1) corpus, generated by
 * @ardrive/turbo-sdk@2.1.0.
 *
 *   node type3.js           regenerate in memory and diff against type3-vectors.json
 *   node type3.js --write   regenerate and write type3-vectors.json
 *
 * Type 3 is deterministic: ECDSA with RFC 6979 nonces, as ethers signs, so a
 * key and an input fix every byte of the signed item, signature and id
 * included. Like the type 4 corpus, this pins COMPLETE signed items.
 *
 * Every case in cases.js is signed twice:
 *
 *   key path     TurboFactory.authenticated({ privateKey, token: "base-eth" }),
 *                which signs with arbundles' EthereumSigner
 *   wallet path  TurboFactory.authenticated({ walletAdapter, token: "base-eth" }),
 *                which signs with InjectedEthereumSigner through a mocked
 *                provider whose signer is an ethers Wallet over the same key
 *
 * and the generator fails unless both give the same bytes. The wallet path
 * also records what the provider was asked to sign: the connect message once
 * (its signature is stored, so a test can replay the key recovery), then the
 * 48 raw deep-hash bytes per item.
 *
 * Keys are derived in code from the case name, so no key material is committed:
 *
 *   private key = SHA-256(UTF-8("turbo-upload type 3 corpus/" + case.name))
 *
 * The public key, the address, the deep hash and the EIP-191 digest come from
 * ethers and arbundles, not from turbo-upload, so the corpus does not lean on
 * the code under test.
 */
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");
const { Buffer } = require("node:buffer");
const ethers = require("ethers");
const arb = require("./arbundles.js");
const cases = require("./cases.js");

const OUT = path.join(__dirname, "type3-vectors.json");
const KEY_PREFIX = "turbo-upload type 3 corpus/";
const CONNECT_MESSAGE = "sign this message to connect to your account";
const SDK_VERSION = JSON.parse(
  fs.readFileSync(path.join(__dirname, "node_modules", "@ardrive", "turbo-sdk", "package.json"), "utf8"),
).version;

const sha256 = (b) => crypto.createHash("sha256").update(b).digest();
const keyFor = (name) => `0x${sha256(Buffer.from(KEY_PREFIX + name, "utf8")).toString("hex")}`;

async function streamToBuffer(stream) {
  const parts = [];
  for await (const part of stream) parts.push(Buffer.from(part));
  return Buffer.concat(parts);
}

let TurboFactory;

const local = {
  // Never contacted: signing is local. Set so nothing defaults to production.
  paymentServiceConfig: { url: "http://127.0.0.1:9" },
  uploadServiceConfig: { url: "http://127.0.0.1:9" },
};

async function signWith(turbo, c) {
  const dataItemOpts = {};
  if (c.tags.length) dataItemOpts.tags = c.tags;
  if (c.target) dataItemOpts.target = c.target;
  if (c.anchor) dataItemOpts.anchor = c.anchor;
  const data = Buffer.from(c.data);
  const { dataItemStreamFactory, dataItemSizeFactory } = await turbo.signer.signDataItem({
    fileStreamFactory: () => data,
    fileSizeFactory: () => data.length,
    dataItemOpts,
  });
  const signed = await streamToBuffer(dataItemStreamFactory());
  if (signed.length !== dataItemSizeFactory()) {
    throw new Error(`${c.name}: turbo-sdk reported ${dataItemSizeFactory()} bytes and produced ${signed.length}`);
  }
  return signed;
}

async function buildVector(c) {
  const privateKey = keyFor(c.name);
  const wallet = new ethers.Wallet(privateKey);

  const keyPath = await signWith(TurboFactory.authenticated({ privateKey, token: "base-eth", ...local }), c);

  const asked = [];
  const provider = {
    getSigner: () => ({
      signMessage: async (m) => {
        asked.push(typeof m === "string" ? { text: m } : { bytes: Buffer.from(m).toString("hex") });
        return wallet.signMessage(m);
      },
      sendTransaction: async () => {
        throw new Error("not in this corpus");
      },
    }),
  };
  const viaWallet = TurboFactory.authenticated({ walletAdapter: provider, token: "base-eth", ...local });
  // turbo-sdk's web signer does this before it signs; the Node signer, which
  // is what loads here, does not, so it is called as the web signer would.
  await viaWallet.signer.signer.setPublicKey();
  const walletPath = await signWith(viaWallet, c);
  if (!walletPath.equals(keyPath)) throw new Error(`${c.name}: the wallet path and the key path signed different bytes`);

  const signature = keyPath.subarray(2, 67);
  const owner = keyPath.subarray(67, 132);
  const deepHash = Buffer.from(await arb.getSignatureData(new arb.DataItem(keyPath)));
  if (asked.length !== 2 || asked[0].text !== CONNECT_MESSAGE || asked[1].bytes !== deepHash.toString("hex")) {
    throw new Error(`${c.name}: the wallet was asked to sign ${JSON.stringify(asked)}`);
  }
  if (`0x${owner.toString("hex")}` !== wallet.signingKey.publicKey) throw new Error(`${c.name}: the owner is not the key's public key`);

  return {
    name: c.name,
    description: c.description,
    address: wallet.address,
    public_key_hex: owner.toString("hex"),
    input: {
      data_hex: Buffer.from(c.data).toString("hex"),
      tags: c.tags,
      target_b64url: c.target ?? null,
      anchor_utf8: c.anchor ?? null,
    },
    expected: {
      deep_hash_hex: deepHash.toString("hex"),
      eip191_digest_hex: ethers.hashMessage(deepHash).slice(2),
      signed_item_hex: keyPath.toString("hex"),
      signed_item_length: keyPath.length,
      signature_hex: signature.toString("hex"),
      id_b64url: sha256(signature).toString("base64url"),
    },
    wallet_path: {
      connect_signature_hex: (await wallet.signMessage(CONNECT_MESSAGE)).slice(2),
      connect_digest_hex: ethers.hashMessage(CONNECT_MESSAGE).slice(2),
    },
  };
}

async function generate() {
  ({ TurboFactory } = await import("@ardrive/turbo-sdk"));
  const vectors = [];
  for (const c of cases) vectors.push(await buildVector(c));
  return {
    format: "ans104-type3-conformance-vectors",
    version: 1,
    generated_by: `@ardrive/turbo-sdk@${SDK_VERSION}`,
    signature_type: {
      id: 3,
      name: "ethereum",
      algorithm: "secp256k1 ECDSA, RFC 6979 nonces, low s, v in {27, 28}",
      signature_length: 65,
      owner_length: 65,
      signed_message:
        'EIP-191 personal_sign over the RAW 48-byte deep hash: keccak256("\\x19Ethereum Signed Message:\\n48" || deep hash)',
    },
    key_rule: `private key = SHA-256(UTF-8("${KEY_PREFIX}" + name)); public key and address by ethers`,
    connect_message: CONNECT_MESSAGE,
    notes: [
      "Every byte under `expected`, signature and id included, must match exactly.",
      "Each item was signed twice, by EthereumSigner (key) and InjectedEthereumSigner (wallet), with identical bytes.",
      "`wallet_path` is what the wallet signed to reveal its public key, before the first item.",
      "No private key is stored: each one is derived from its case name by the key rule.",
    ],
    vectors,
  };
}

(async () => {
  const corpus = await generate();
  const text = JSON.stringify(corpus, null, 2) + "\n";
  if (process.argv.includes("--write")) {
    fs.writeFileSync(OUT, text);
    console.log(`wrote ${path.basename(OUT)}: ${corpus.vectors.length} vectors from ${corpus.generated_by}, ` +
      `${(Buffer.byteLength(text) / 1024).toFixed(1)} KiB`);
    return;
  }
  const committed = fs.readFileSync(OUT, "utf8");
  if (committed !== text) {
    const want = JSON.parse(committed).vectors;
    for (const v of corpus.vectors) {
      const w = want.find((x) => x.name === v.name);
      if (!w || JSON.stringify(w) !== JSON.stringify(v)) console.error(`  DIFFERS: ${v.name}`);
    }
    console.error(`type3-vectors.json does not match what ${corpus.generated_by} produces today.`);
    process.exit(1);
  }
  console.log(`type3-vectors.json matches ${corpus.generated_by}: ${corpus.vectors.length} vectors regenerated, ` +
    "byte-identical, key path and wallet path");
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
